import pg from './node_modules/pg/lib/index.js';
import { readFileSync } from 'fs';
const { Pool } = pg;
const rawUrl = String(process.env.DATABASE_URL||'');
const url = (() => { try { const u = new URL(rawUrl); ['sslmode','sslcert','sslkey','sslrootcert','sslpassword'].forEach(p=>u.searchParams.delete(p)); return u.toString(); } catch { return rawUrl; } })();
let ssl;
try { ssl = { rejectUnauthorized: true, ca: readFileSync('./certs/rds-ca-bundle.pem') }; } catch { ssl = { rejectUnauthorized: false }; }
const pool = new Pool({ connectionString: url, ssl, max: 1 });
const c = await pool.connect();
const { rows } = await c.query('SELECT COUNT(*)::int AS cnt FROM cid10');
console.log('CID10 COUNT=' + rows[0].cnt);
const { rows: ciap } = await c.query('SELECT COUNT(*)::int AS cnt FROM ciap2');
console.log('CIAP2 COUNT=' + ciap[0].cnt);
const { rows: mun } = await c.query('SELECT COUNT(*)::int AS cnt FROM municipalities');
console.log('MUNICIPALITIES COUNT=' + mun[0].cnt);
const { rows: rp } = await c.query("SELECT name, uf FROM municipalities WHERE ibge_code = '3534401'");
console.log('3534401=' + (rp[0] ? rp[0].name + '/' + rp[0].uf : 'NOT FOUND'));
const { rows: r81 } = await c.query("SELECT description FROM ciap2 WHERE code = 'R81'");
console.log('CIAP2 R81=' + (r81[0] ? r81[0].description : 'NOT FOUND'));
c.release(); await pool.end();
